const aiYaniti = $input.first().json;

// Gemini çıktısındaki metni güvenli şekilde alıyoruz
let hamMetin = "";
if (aiYaniti.content && aiYaniti.content.parts && aiYaniti.content.parts[0]) {
  hamMetin = aiYaniti.content.parts[0].text;
} else if (aiYaniti.text) {
  hamMetin = aiYaniti.text;
} else {
  throw new Error("Yapay zeka yanıtından metin alınamadı.");
}

// Olası markdown bloklarını (```json ... ```) temizliyoruz
const temizMetin = hamMetin.replace(/```json/gi, "").replace(/```/g, "").trim();

// Metni gerçek JSON nesnesine dönüştürüyoruz
let veri;
try {
  veri = JSON.parse(temizMetin);
} catch (err) {
  throw new Error("JSON ayrıştırma hatası: " + temizMetin);
}

// Tutarı sayısal (Float) değere çeviriyoruz
const sayisalTutar = parseFloat(String(veri.Tutar || "0").replace(/[^0-9.-]+/g, ""));

// Google Sheets sütun başlıklarıyla birebir eşleşen temiz veri nesnesi
return [
  {
    json: {
      Tarih: veri.Tarih || new Date().toISOString().split("T")[0],
      Belge_Turu: veri.Belge_Turu || "Dekont/Fatura",
      Gonderici: veri.Gonderici || "Belirtilmemiş",
      Gonderici_IBAN: veri.Gonderici_IBAN ? String(veri.Gonderici_IBAN).replace(/\s+/g, "") : "Belirtilmemiş",
      Alici: veri.Alici || "Belirtilmemiş",
      Alici_IBAN: veri.Alici_IBAN ? String(veri.Alici_IBAN).replace(/\s+/g, "") : "Belirtilmemiş",
      Tutar: isNaN(sayisalTutar) ? 0 : sayisalTutar,
      Para_Birimi: (veri.Para_Birimi || "TRY").toUpperCase()
    }
  }
];
